local R=dofile('tests/kernel_automedic_client_harness.lua')
local n=0
local function case(name,fn)R.case(name,fn);n=n+1 end
local function payload()return {token='T',bed=R.A.bed('bed',10)}end
for _,invalid in ipairs({false,{}, {bed={}}, {token='T',bed={}}, {token=4,bed=R.A.bed('a')}})do
    case('invalid-payload-'..tostring(n),function(r)assert(not r.hospital.recover(invalid,function()end))end)
end
case('recover-pose',function(r)
    assert(r.hospital.recover(payload(),function(ped)r.native.SetEntityHealth(ped,110)end));r.advance(1)
    assert(r.hospital.isRecovering()and r.health==110 and r.positions[11].z==2 and not r.faded)
end)
case('recover-replaces',function(r)r.hospital.recover(payload(),function()end);r.advance(1)
    local p=payload();p.token='new';r.hospital.recover(p,function()end);r.advance(1);assert(r.hospital.current.token=='new')end)
case('clear-release',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.hospital.clear(true);assert(not r.hospital.isRecovering())end)
case('clear-no-release',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.hospital.clear(false)end)
case('clear-empty',function(r)r.hospital.clear(true);r.hospital.clear(true)end)
case('leave-empty',function(r)assert(not r.hospital.leave())end)
case('leave-alive',function(r)r.dead=false;r.health=110;r.hospital.recover(payload(),function()end);r.advance(1)
    assert(r.hospital.leave());assert(not r.hospital.leave());r.advance(5000);assert(not r.hospital.isRecovering()and r.positions[11].y==1)end)
case('leave-dead',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.hospital.leave();r.advance(1);assert(not r.hospital.isRecovering())end)
case('leave-keybind',function(r)r.hospital.recover(payload(),function()end);r.advance(1);assert(r.binds[1].onPressed());r.advance(5000)end)
case('stop-other',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.fire('onResourceStop',0,'other');assert(r.hospital.isRecovering())end)
case('stop-own',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.fire('onResourceStop',0,'forge-core');assert(not r.hospital.isRecovering())end)
case('session-clear',function(r)r.hospital.recover(payload(),function()end);r.advance(1);r.fire('forge-core:session:changed',0);assert(not r.hospital.isRecovering())end)
case('collision-await-clear',function(r)r.collision=false;r.hospital.recover(payload(),function()error('fixture-late-apply')end)
    r.advance(1);r.hospital.clear(true);r.advance(5100);assert(not r.hospital.isRecovering())end)
case('animation-await-clear',function(r)r.animation=false;r.hospital.recover(payload(),function()end);r.advance(1)
    r.fire('forge-core:session:changed',0);r.advance(5100);assert(not r.hospital.isRecovering())end)
case('animation-fails',function(r)r.animation=false;r.hospital.recover(payload(),function()end);r.advance(5100);assert(not r.hospital.isRecovering())end)
case('apply-error',function(r)r.hospital.recover(payload(),function()error('fixture-apply',0)end);r.advance(1);assert(not r.hospital.isRecovering())end)
case('apply-reentry-retained',function(r)r.hospital.recover(payload(),function()r.hospital.clear(true)end);r.advance(1);assert(not r.hospital.isRecovering())end)
case('leave-generation',function(r)r.dead=false;r.health=110;r.hospital.recover(payload(),function()end);r.advance(1);r.hospital.leave();r.advance(1)
    r.hospital.clear(true);r.advance(5000);assert(not r.hospital.isRecovering())end)
case('revive-hospital',function(r)r.fire(r.config.AutoMedic.Events.revive,65535,payload());r.advance(1);assert(r.hospital.isRecovering()and r.health==110)end)
print('PASS AutoMedic client hospital differentials '..n)
